/* ============================================
   Volta Studio — Corporate Website Styles
   Minimal, editorial, warm
   ============================================ */

/* CSS Variables */
:root {
  --bg: #F5F2ED;
  --bg-warm: #EDE9E3;
  --text: #1A1A1A;
  --text-muted: #6B6560;
  --accent-terracotta: #C4705A;
  --accent-sage: #8A9B7A;
  --accent-sand: #D4C4A8;
  --border: rgba(26, 26, 26, 0.12);
  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Reset & Base */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-sans);
  color: var(--text);
  background-color: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
  transition: opacity var(--transition);
}

a:hover {
  opacity: 0.6;
}

img {
  max-width: 100%;
  display: block;
}

/* ============================================
   Typography
   ============================================ */

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

.display-xl {
  font-family: var(--font-serif);
  font-size: clamp(3rem, 8vw, 7rem);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.03em;
}

.display-lg {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.display-md {
  font-family: var(--font-serif);
  font-size: clamp(1.75rem, 4vw, 3rem);
  font-weight: 700;
  line-height: 1.2;
}

.body-lg {
  font-family: var(--font-sans);
  font-size: clamp(1.125rem, 1.5vw, 1.375rem);
  line-height: 1.7;
  color: var(--text-muted);
}

.body-md {
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.7;
  color: var(--text-muted);
}

.label {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-muted);
}

/* ============================================
   Layout Utilities
   ============================================ */

.container {
  width: 100%;
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 clamp(1.5rem, 5vw, 4rem);
}

.container-narrow {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  padding: 0 clamp(1.5rem, 5vw, 4rem);
}

.section {
  padding: clamp(4rem, 10vw, 8rem) 0;
}

.section-sm {
  padding: clamp(2rem, 5vw, 4rem) 0;
}

/* ============================================
   Header & Navigation
   ============================================ */

.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: clamp(1rem, 3vw, 1.5rem) clamp(1.5rem, 5vw, 4rem);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: rgba(245, 242, 237, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid transparent;
  transition: border-color var(--transition);
}

.header.scrolled {
  border-bottom-color: var(--border);
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text);
}

.logo:hover {
  opacity: 0.6;
}

.nav-desktop {
  display: flex;
  align-items: center;
  gap: 2.5rem;
}

.nav-desktop a {
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  position: relative;
}

.nav-desktop a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 1px;
  background: var(--text);
  transition: width var(--transition);
}

.nav-desktop a:hover::after,
.nav-desktop a.active::after {
  width: 100%;
}

.nav-desktop a:hover {
  opacity: 1;
}

/* Mobile Menu Toggle */
.menu-toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 32px;
  height: 32px;
  gap: 5px;
  cursor: pointer;
  z-index: 110;
  background: none;
  border: none;
}

.menu-toggle span {
  display: block;
  width: 24px;
  height: 1.5px;
  background: var(--text);
  transition: all var(--transition);
  transform-origin: center;
}

.menu-toggle.active span:nth-child(1) {
  transform: translateY(6.5px) rotate(45deg);
}

.menu-toggle.active span:nth-child(2) {
  opacity: 0;
}

.menu-toggle.active span:nth-child(3) {
  transform: translateY(-6.5px) rotate(-45deg);
}

/* Mobile Overlay Menu */
.mobile-menu {
  position: fixed;
  inset: 0;
  z-index: 90;
  background: var(--bg);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2rem;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition);
}

.mobile-menu.active {
  opacity: 1;
  pointer-events: all;
}

.mobile-menu a {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 6vw, 3.5rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  transition: opacity var(--transition);
}

.mobile-menu a:hover {
  opacity: 0.5;
}

/* ============================================
   Hero
   ============================================ */

.hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding-top: 80px;
  padding-bottom: clamp(3rem, 8vw, 6rem);
}

.hero-title {
  max-width: 900px;
  margin-bottom: clamp(3rem, 6vw, 5rem);
}

/* ============================================
   Media Showcase (Triptych)
   ============================================ */

.media-showcase {
  width: 100%;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(0.5rem, 2vw, 1.5rem);
  margin-top: auto;
}

.media-showcase .media-item {
  aspect-ratio: 4 / 5;
  width: 100%;
  border-radius: 4px;
}

.media-showcase .media-item:nth-child(1) {
  background: var(--accent-terracotta);
}

.media-showcase .media-item:nth-child(2) {
  background: var(--accent-sage);
}

.media-showcase .media-item:nth-child(3) {
  background: var(--accent-sand);
}

/* ============================================
   Client Marquee
   ============================================ */

.marquee-section {
  overflow: hidden;
  padding: clamp(3rem, 8vw, 6rem) 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.marquee-row {
  display: flex;
  width: max-content;
  will-change: transform;
}

.marquee-track {
  display: flex;
  align-items: center;
  gap: clamp(2rem, 5vw, 4rem);
  padding-right: clamp(2rem, 5vw, 4rem);
  flex-shrink: 0;
}

.marquee-item {
  font-family: var(--font-serif);
  font-size: clamp(1.75rem, 4vw, 3rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  white-space: nowrap;
  color: var(--text);
  opacity: 0.25;
  transition: opacity var(--transition);
}

.marquee-item:hover {
  opacity: 1;
}

.marquee-divider {
  font-size: clamp(1rem, 2vw, 1.5rem);
  opacity: 0.2;
}

/* Row animations */
@keyframes marquee-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

.marquee-row.row-1 {
  animation: marquee-left 40s linear infinite;
}

.marquee-row.row-2 {
  animation: marquee-right 45s linear infinite;
}

.marquee-row.row-3 {
  animation: marquee-left 50s linear infinite;
}

.marquee-row:hover {
  animation-play-state: paused;
}

/* ============================================
   About Section
   ============================================ */

.about-section {
  padding: clamp(4rem, 10vw, 8rem) 0;
}

.about-section .label {
  margin-bottom: 2rem;
  display: block;
}

.about-text {
  max-width: 800px;
}

.about-text p + p {
  margin-top: 1.5rem;
}

/* ============================================
   Founder Letter (Editorial)
   ============================================ */

.page-header-spacer {
  height: 80px;
}

.letter-section {
  padding: clamp(3rem, 8vw, 6rem) 0 clamp(6rem, 15vw, 10rem);
}

.letter-header {
  margin-bottom: clamp(3rem, 6vw, 5rem);
}

.letter-header .label {
  margin-bottom: 1.5rem;
  display: block;
}

.letter-body {
  font-family: var(--font-sans);
  font-size: clamp(1.0625rem, 1.5vw, 1.25rem);
  line-height: 1.85;
  color: var(--text-muted);
}

.letter-body p + p {
  margin-top: 1.75rem;
}

.letter-body strong {
  color: var(--text);
  font-weight: 600;
}

.letter-body em {
  font-style: italic;
  color: var(--text);
}

.letter-signoff {
  margin-top: clamp(3rem, 6vw, 5rem);
  padding-top: 2rem;
  border-top: 1px solid var(--border);
}

.letter-signoff p {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 2vw, 1.75rem);
  font-weight: 700;
  color: var(--text);
  font-style: italic;
}

/* ============================================
   Philosophy
   ============================================ */

.philosophy-section {
  padding: clamp(4rem, 10vw, 8rem) 0;
}

.philosophy-heading {
  margin-bottom: clamp(2rem, 4vw, 3rem);
}

.philosophy-body {
  max-width: 800px;
}

.philosophy-body p + p {
  margin-top: 1.5rem;
}

/* ============================================
   Divider
   ============================================ */

.divider {
  height: 1px;
  background: var(--border);
  margin: 0 auto;
  max-width: 1400px;
  width: calc(100% - clamp(3rem, 10vw, 8rem));
}

/* ============================================
   Service Details
   ============================================ */

.services-section {
  padding: clamp(4rem, 10vw, 8rem) 0;
}

.services-section .label {
  margin-bottom: 3rem;
  display: block;
}

.service-list {
  display: flex;
  flex-direction: column;
  gap: clamp(3rem, 6vw, 5rem);
}

.service-item {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: clamp(2rem, 4vw, 4rem);
  align-items: start;
}

.service-item h3 {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 700;
  position: sticky;
  top: 120px;
}

.service-item p {
  color: var(--text-muted);
  font-size: clamp(1rem, 1.2vw, 1.125rem);
  line-height: 1.75;
}

/* ============================================
   Clients Page
   ============================================ */

.clients-heading {
  padding: clamp(4rem, 10vw, 8rem) 0 clamp(2rem, 4vw, 3rem);
}

.clients-heading .label {
  margin-bottom: 1.5rem;
  display: block;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(2rem, 4vw, 4rem);
  padding-bottom: clamp(4rem, 10vw, 8rem);
}

.client-card h3 {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 2vw, 1.75rem);
  font-weight: 700;
  margin-bottom: 0.75rem;
}

.client-card p {
  font-size: 0.9375rem;
  line-height: 1.65;
  color: var(--text-muted);
}

/* ============================================
   Contact Page
   ============================================ */

.contact-hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 80px clamp(1.5rem, 5vw, 4rem) clamp(3rem, 8vw, 6rem);
}

.contact-title {
  margin-bottom: clamp(2rem, 5vw, 4rem);
}

.contact-links {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.contact-links a {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 2.5vw, 1.875rem);
  font-weight: 700;
  position: relative;
  display: inline-block;
}

.contact-links a::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 50%;
  width: 0;
  height: 1px;
  background: var(--text);
  transition: all var(--transition);
  transform: translateX(-50%);
}

.contact-links a:hover::after {
  width: 100%;
}

.contact-links a:hover {
  opacity: 1;
}

/* ============================================
   Footer
   ============================================ */

.footer {
  padding: clamp(2rem, 4vw, 3rem) clamp(1.5rem, 5vw, 4rem);
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* ============================================
   Responsive
   ============================================ */

@media (max-width: 900px) {
  .nav-desktop {
    display: none;
  }

  .menu-toggle {
    display: flex;
  }

  .media-showcase {
    grid-template-columns: 1fr;
  }

  .media-showcase .media-item {
    aspect-ratio: 16 / 9;
  }

  .service-item {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .service-item h3 {
    position: static;
  }

  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .clients-grid {
    grid-template-columns: 1fr;
  }

  .footer {
    flex-direction: column;
    gap: 0.5rem;
    text-align: center;
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .marquee-row {
    animation: none !important;
  }
}
